    # If only 1 stock exists, routing it away would violate BOTH_CLASSES_REQUIRED -> Must escalate
    res1 = FormatValidator.handle_source_failure(FormatId.F2, "main_stock", attempts=2, current_stock_count=1)
    assert res1["disposition"] == "NEEDS_OWNER_OR_FAIL"

    # If >1 stock exists, routing one interval to AI video is safe
    res2 = FormatValidator.handle_source_failure(FormatId.F2, "main_stock", attempts=2, current_stock_count=3)
    assert res2["disposition"] == "ROUTE_TO_GENERATED_VIDEO"
