def test_preview_candidate_mismatch_raises_artifact_ambiguous(tmp_path):
    final_file = tmp_path / "final_pexels_12345.mp4"
    final_file.write_bytes(b"x" * 20000)

    # Preview metadata has duration 15.0s, but actual acquired file is reported with material duration discrepancy
    preview_meta = {
        "id": "12345",
        "online_id": "pexels_12345",
        "duration": 15.0,
        "width": 1920,
        "height": 1080
    }

    # Simulate inspection returning 8.0s (difference > 1.5s tolerance)
    from videopipeline.stages.stage4_render.qa_verifier import QAVerifier
    orig_inspect = QAVerifier.inspect_stream_metadata
    try:
        QAVerifier.inspect_stream_metadata = lambda p: {"duration": 8.0, "width": 1920, "height": 1080}
        res = reconcile_preview_to_final_asset(preview_meta, final_file, duration_tolerance_sec=1.5)
        assert res["reconciled"] is False
        assert res["status"] == "ARTIFACT_AMBIGUOUS"
        assert "exceeds tolerance" in res["message"]
    finally:
        QAVerifier.inspect_stream_metadata = orig_inspect


